// Custom backgrounds: copies chosen by the native picker, served with HTTP byte ranges.
const {
  statSync,
  createReadStream,
  mkdirSync,
  copyFileSync,
  readdirSync,
  rmSync,
} = require('node:fs');
const { extname, join } = require('node:path');
const { randomBytes } = require('node:crypto');
const { Readable } = require('node:stream');

/** Names generated by {@link createMediaStore}; never a renderer-provided path. */
const MEDIA_ID = /^[a-f0-9]{32}\.(png|jpg|jpeg|webp|mp4|webm)$/;
const MAX_MEDIA_BYTES = 250 * 1024 * 1024;
const EXTENSIONS = { image: ['.png', '.jpg', '.jpeg', '.webp'], video: ['.mp4', '.webm'] };
const types = {
  '.mp4': 'video/mp4',
  '.webm': 'video/webm',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
};

/**
 * Answers a GET or HEAD request for a local file, honouring a single `Range` header.
 * @param {string} file
 * @param {Request} request
 * @returns {Response}
 */
function serveMedia(file, request) {
  const size = statSync(file).size;
  const headers = {
    'Accept-Ranges': 'bytes',
    'Content-Type': types[extname(file)] || 'application/octet-stream',
    'Cache-Control': 'no-store',
  };
  if (!['GET', 'HEAD'].includes(request.method)) {
    return new Response(null, { status: 405, headers: { Allow: 'GET, HEAD' } });
  }
  const unsatisfiable = () =>
    new Response(null, {
      status: 416,
      headers: { ...headers, 'Content-Range': `bytes */${size}` },
    });
  let start = 0;
  let end = size - 1;
  let status = 200;
  const range = request.headers.get('range');
  if (range) {
    const match = /^bytes=(\d*)-(\d*)$/.exec(range);
    if (!match || (!match[1] && !match[2])) return unsatisfiable();
    const [, first, last] = match;
    start = first ? Number(first) : Math.max(0, size - Number(last));
    if (first && last) end = Math.min(end, Number(last));
    const valid = Number.isSafeInteger(start) && Number.isSafeInteger(end);
    if (!valid || start < 0 || start > end || start >= size) return unsatisfiable();
    status = 206;
    headers['Content-Range'] = `bytes ${start}-${end}/${size}`;
  }
  headers['Content-Length'] = String(Math.max(0, end - start + 1));
  if (request.method === 'HEAD' || !size) return new Response(null, { status, headers });
  const stream = createReadStream(file, { start, end });
  return new Response(Readable.toWeb(stream), { status, headers });
}

/**
 * Owns the folder of background copies so that only the active one is kept on disk.
 * @param {string} directory
 */
function createMediaStore(directory) {
  mkdirSync(directory, { recursive: true });
  const path = id => join(directory, id);
  const exists = id => {
    try {
      return MEDIA_ID.test(id || '') && statSync(path(id)).isFile();
    } catch {
      return false;
    }
  };
  const remove = id => {
    if (!MEDIA_ID.test(id || '')) return;
    try {
      rmSync(path(id), { force: true });
    } catch {
      /* A file still being streamed is removed on the next launch. */
    }
  };
  return {
    exists,
    remove,
    /** @param {Request} request */
    serve(request) {
      const url = new URL(request.url);
      const id = url.pathname.slice(1);
      if (url.host !== 'background' || !exists(id)) return new Response('', { status: 404 });
      return serveMedia(path(id), request);
    },
    /**
     * Copies a picked file and returns its new identifier.
     * Errors carry a dictionary key as their message.
     * @param {string} source
     * @param {'image'|'video'} kind
     */
    import(source, kind) {
      const extension = extname(source).toLowerCase();
      if (!EXTENSIONS[kind]?.includes(extension)) throw new Error('invalidMedia');
      if (statSync(source).size > MAX_MEDIA_BYTES) throw new Error('mediaTooLarge');
      const id = randomBytes(16).toString('hex') + extension;
      copyFileSync(source, path(id));
      return id;
    },
    /** Deletes every stored background except `id`. */
    keepOnly(id) {
      for (const file of readdirSync(directory)) if (file !== id) remove(file);
    },
  };
}

module.exports = { MEDIA_ID, MAX_MEDIA_BYTES, EXTENSIONS, serveMedia, createMediaStore };
